using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Catalog;using MediDesk.Common.Contracts.Finance;namespace MediDesk.Business.Services;public sealed class AccountService(IAccountRepository r):IAccountService{public Task<PagedResponse<AccountEntryDto>>GetPageAsync(AccountQuery q,CancellationToken ct)=>r.GetPageAsync(q with{Search=q.Search?.Trim(),Page=Math.Max(1,q.Page),PageSize=Math.Clamp(q.PageSize,1,200)},ct);public Task<AccountEntryDto>CreateAsync(CreateAccountEntryRequest x,long u,CancellationToken ct)=>r.CreateAsync(x with{EntryType=x.EntryType.Trim(),AccountName=x.AccountName.Trim(),PaymentMode=x.PaymentMode.Trim(),Reference=string.IsNullOrWhiteSpace(x.Reference)?null:x.Reference.Trim()},u,ct);}

